import 'package:audioplayers/audioplayers.dart';

/// Toy-box audio: synthesized wooden knocks, crayon scratches, marimba music.
/// All assets generated by tool/synth_audio.py (no recordings, no AI art).
class ToyAudio {
  ToyAudio._();
  static final ToyAudio instance = ToyAudio._();

  bool sfxOn = true;
  bool musicOn = true;
  double sfxVolume = 0.8;
  double musicVolume = 0.6;

  final AudioPlayer _music = AudioPlayer();
  final List<AudioPlayer> _sfxPool = List.generate(4, (_) => AudioPlayer());
  int _sfxIdx = 0;
  String? _currentTrack;

  Future<void> init() async {
    await _music.setReleaseMode(ReleaseMode.loop);
    for (final p in _sfxPool) {
      await p.setPlayerMode(PlayerMode.lowLatency);
    }
  }

  Future<void> playMusic(String asset) async {
    if (_currentTrack == asset) {
      if (musicOn) await _music.resume();
      return;
    }
    _currentTrack = asset;
    if (!musicOn) return;
    try {
      await _music.stop();
      await _music.setVolume(musicVolume);
      await _music.play(AssetSource('audio/$asset'));
    } catch (_) {/* audio is best-effort */}
  }

  Future<void> stopMusic() async {
    _currentTrack = null;
    try {
      await _music.stop();
    } catch (_) {}
  }

  Future<void> pauseMusic() async {
    try {
      await _music.pause();
    } catch (_) {}
  }

  Future<void> resumeMusic() async {
    if (musicOn && _currentTrack != null) {
      try {
        await _music.resume();
      } catch (_) {}
    }
  }

  Future<void> applyVolumes() async {
    try {
      await _music.setVolume(musicVolume);
    } catch (_) {}
  }

  Future<void> sfx(String asset) async {
    if (!sfxOn) return;
    final p = _sfxPool[_sfxIdx++ % _sfxPool.length];
    try {
      await p.setVolume(sfxVolume);
      await p.play(AssetSource('audio/$asset'));
    } catch (_) {/* best-effort */}
  }

  Future<void> dispose() async {
    try {
      await _music.dispose();
      for (final p in _sfxPool) {
        await p.dispose();
      }
    } catch (_) {}
  }
}
